quests[41196] = { id = 41196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leysteinbasilisken" }
quests[41197] = { id = 41197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück ins Körbchen", description = "Während Ihr Euch um das davongelaufene Eulenkätzchen gekümmert habt, habe ich mich ein wenig umgesehen.\n\nAnscheinend haben diese neugierigen Wesen die Angewohnheit, den wachsamen Blicken ihrer Eltern zu entfleuchen. Einige wurden jenseits des Weges von einem umherstreifenden Ettin eingefangen.\n\nEr scheint sie wohl... nun ja... zu fressen.\n\nWir können uns Jaulons Segen verdienen, indem wir seine Kinder heimbringen.", sourceObjective = "Treibt 7 verirrte Federmähnenkätzchen zurück nach Hause.", progress = "Habt Ihr welche retten können?", completion = "Sie sehen so glücklich aus, wieder daheim zu sein. Ausgezeichnete Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
