quests[41213] = { id = 41213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Cho'Zok" }
quests[41214] = { id = 41214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stück um Stück", description = "Brambley... Ich kann es immer noch nicht glauben.\n\nIch kann ihn nicht hierlassen... nicht an diesem Ort... nicht so.\n\nHelft mir, den Rest von ihm zu finden, damit ich seine Überreste nach Hause bringen kann, wo er hingehört.\n\nEr soll ein anständiges Begräbnis erhalten, denn das hat er sich verdient!", sourceObjective = "Sammelt Brambley Morrisons Überreste ein.", progress = "Also, haben wir alles? Wir haben doch nichts übersehen, oder?", completion = "<Angus wischt sich Tränen aus den Augen während er spricht.>\n\nBrambley... Ich verspreche Euch die beste Beerdigung, die man mit Geld kaufen kann! Und so viel Gebräu, wie man trinken kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[41215] = { id = 41215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Jägern zu Gejagten", description = "Der Fallensteller, den Ihr getötet habt, war nur einer von vielen.\n\nDie Nachtgeborenen knechten die hiesigen Tiere, nur um sich an ihrem Anblick zu erfreuen. Ich glaube, wir können sie gleich zweifach empfindlich treffen.\n\nBringt diese Fallensteller zur Strecke, {race}. Sie sollen lernen, ihre Beute zu respektieren.", sourceObjective = "Tötet 6 Fallensteller der Nachtgeborenen.", completion = "Ausgezeichnete Arbeit. Sie respektieren die Jagd nicht, also muss man sie in ihre Schranken weisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41216] = { id = 41216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überleben des Stärkeren", description = "Das Halsband, das Ihr dem Fallensteller abgenommen habt, ist einfach, aber effektiv. Wenn man es einem Ziel anlegt, wird es gefügig und unterwirft sich seinen nachtgeborenen Meistern. Lilryia konnte diesen Effekt mithilfe der Fallen, die Ihr gefunden habt, umkehren.\n\nMit der Magie dieses Halsbandes lassen sich jetzt die Effekte der anderen Halsbänder aufheben.\n\nWollen wir jetzt den Nachtgeborenen beibringen, dass die Natur immer einen Weg findet?", sourceObjective = "Befreit 12 Kreaturen aus der Menagerie.", completion = "Ich konnte mich selbst hier an ihren Schreien und Schmerzen erfreuen! Jetzt sollten die Nachtgeborenen wissen, dass man keine Tiere versklaven darf. Sind sie in all diesen Jahren unter dem Schild wirklich so tief gesunken?", sourceObjectiveStatus = "unverified-source-field" }
quests[41217] = { id = 41217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den kontaminierten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Und <jeder/jede:c> {class}, wie Ihr es <einer/eine:c> seid, wird eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nMuffinus Chrombräu wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche beaufsichtigen. Er erwartet Euch auf der Tribüne auf der anderen Straßenseite.", sourceObjective = "Sucht Muffinus Chrombräu in Neu-Tüftlerstadt auf.", completion = "Für einen {race}, der so viel Zeit in Gnomeregan verbracht hat, seht Ihr aus wie das blühende Leben, {name}. Das ist gut. Bevor wir das abschließen können, was mit Operation: Gnomeregan begonnen wurde, brauchen wir mehr {class} wie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[41218] = { id = 41218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin hat mir erzählt, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill, oder Hochtüftler Mekkadrill, um es genau zu nehmen, ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", completion = "Schön, Euch kennenzulernen, {name}. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[41219] = { id = 41219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blühende Fuchsblume" }
quests[41220] = { id = 41220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Azsuna", description = "{name}, wir müssen einen Weg finden, um das Grabmal des Sargeras wieder zu versiegeln.\n\nIch habe Informationen zu einem uralten Relikt in Erfahrung gebracht. Dieses Relikt ist vielleicht der Schlüssel, um die Legion aufzuhalten.\n\nUnsere Suche beginnt auf der uralten Elfeninsel Azsuna. Vor langer Zeit haben dort die Hochgeborenen von Suramar ihre mächtigsten Magien perfektioniert. Jetzt findet sich dort nur noch eine verfluchte Ruine.\n\nDie Dämonenjäger der Illidari haben ein Lager auf der Insel errichtet. Da wir sonst niemanden in diesem Gebiet kennen, werden wir dort anfangen.\n\nSeid Ihr bereit für einen Flug?", sourceObjective = "Sprecht mit Erzmagier Khadgar, um nach Azsuna zu fliegen.", completion = "Wie vermutet gelingt es den Illidari, die Front gegen die Brennende Legion zu halten, aber sie haben Probleme.\n\nWir müssen ihnen helfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41221] = { id = 41221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Mardum", description = "Das Tor ist voll funktionsfähig, {name}. Uhh, ich zittere schon vor Aufregung!\n\nLasst Jace und die anderen wissen, dass wir Eure Ankunft gespannt erwarten. Es gibt so viel zu tun und nur so wenig Zeit.\n\nIhr werdet uns doch sicher beistehen, nicht wahr?", sourceObjective = "Durchschreitet das Illidaritor, um in Mardum an Bord der Teufelshammer zu gehen.", completion = "Diese Zitadelle war eine der wichtigsten Festen der Legion. Sie wird uns gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[41222] = { id = 41222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Grube!", description = "Die Teufelspirschergruben?!\n\nDann dürfen wir keine Zeit verschwenden, {name}!\n\nIch weiß nicht, was die Brennende Legion mit dem alten Brambley vorhat, aber es ist sicher nichts Gutes!\n\nBeeilung! Wir müssen ihn finden, bevor die Brennende Legion ihm etwas antut!", sourceObjective = "Begleitet Angus zur Höhle der Teufelsrachen in der Teufelsseelenbastion.", progress = "Wir müssen zu den Teufelspirschergruben und Brambley retten!", completion = "Das darf nicht wahr sein!\n\nBrambley... mein guter alter Freund! Warum nur musstet Ihr sterben?", sourceObjectiveStatus = "unverified-source-field" }
quests[41223] = { id = 41223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Fuchsblume", progress = "Bringt Ihr die angeforderten Vorräte?", completion = "Vielen Dank, Kräuterkundiger. Diese Fuchsblume wird einem guten Zweck dienen." }
