quests[41229] = { id = 41229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chen Obtained" }
quests[41230] = { id = 41230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallenstellen für Fortgeschrittene", description = "Die Nachtgeborenen nutzen die Magie einfach für alles, sogar das Fallenstellen.\n\nNachtauge hat gesehen, dass sie andere Fallen als wir nutzen, um ihre Beute zu fangen. Sie verwenden magische Fesselungsfallen.\n\nBringt mir ihre Fallen, damit ich sie mir genauer ansehen kann.", sourceObjective = "Sammelt 4 arkane Fallen für Lilryia ein.", progress = "Habt Ihr die Fesselungsfallen, {race}?", completion = "Das sind seltsame Geräte. Sie sehen aus wie die Fallen unserer Jäger, aber sie können die Tiere in der Nähe mithilfe von Magie anlocken und fangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41231] = { id = 41231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitze der Nahrungskette", description = "Ich habe gute und schlechte Neuigkeiten, {race}.\n\nDie schlechten Neuigkeiten sind, dass sie es irgendwie geschafft haben, einen Teufelssaurier zu fangen und abzurichten.\n\nDie guten Neuigkeiten sind, dass er kein Halsband trägt und zahm zu sein scheint. Offenbar hält er einen der Nachtgeborenen für seinen Meister. Findet diesen Rudelführer und schaltet ihn aus, um damit die Bestie auf die anderen loszulassen.", sourceObjective = "Sucht und tötet den Nachtgeborenen, der Su'esh kontrolliert.", completion = "Ich habe alles von hier draußen gesehen. Das war... unschön.", sourceObjectiveStatus = "unverified-source-field" }
quests[41232] = { id = 41232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicker Eisenhornbalg" }
