quests[41253] = { id = 41253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandernder Hochberglachs" }
quests[41255] = { id = 41255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sät, der wird ernten", description = "Eure Waffe ist uralt und mächtig, aber sie birgt noch sehr viel mehr Potenzial.\n\nNehmt diesen Samen. Er ist alles, was von einem riesigen Wald übrig blieb, der zu Anbeginn dieser Welt gedieh. Pflanzt ihn im Hain westlich von hier ein und lasst ihn Wurzeln schlagen.\n\nVon seinen Kräften werden sowohl der Hain als auch Eure Waffe erheblich profitieren.", sourceObjective = "Pflanzt die Saat der Zeitalter in die weiche Erde im Hain der Träume.", completion = "Ausgezeichnet. Wir haben keine Zeit zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[41256] = { id = 41256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Fischwürze", description = "Ich habe eine Zutat, die mein Obst unwiderstehlich machen wird.\n\nEs wissen nicht mehr viele, was für eine Delikatesse Manaforellensaft ist. Dieses scharfe Aroma, dieses sämige Gefühl im Mund...\n\nDie Kröten in der Nähe des nördlichen Flusses speichern diese Zutat in ihren Muskelmägen. Holt mir ein paar dieser Mägen, damit wir genug von dem Stoff haben.", sourceObjective = "Sammelt Krötenmuskelmägen für Keelay.", progress = "Daglir ist jung und töricht!", completion = "Manaforellen waren in den Häfen komplett überfischt. Seitdem der Schild errichtet wurde, blieb uns von diesem Saft nicht mehr als eine geschmackliche Erinnerung.", sourceObjectiveStatus = "unverified-source-field" }
quests[41257] = { id = 41257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm der Wächterinnen: Cordanas Apex" }
quests[41258] = { id = 41258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frucht der Verdammnis", description = "Jetzt ist es an der Zeit zuzuschlagen.\n\nSchattenblüten haben... außerordentliche Verdauungseigenschaften. Träufelt davon etwas über Daglirs Obstschalen und beobachtet, was dann passiert.\n\nIn der Zwischenzeit werde ich den Manaforellensaft verwenden, um meine Stellung als bester Obstverkäufer der Stadt zu festigen.", sourceObjective = "Vergiftet 3 Obstschalen.", completion = "Ein Sieg ist süßer als jede Frucht, selbst wenn sie von mir kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41259] = { id = 41259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speckstreifen" }
