quests[41306] = { id = 41306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Lion" }
quests[41307] = { id = 41307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was glänzt", description = "Da jetzt der Schild fort ist, denke ich öfter an die älteren Siedlungen außerhalb der Stadt.\n\nWusstet Ihr, dass ich an den Verzierungsarbeiten für die vielen arkanen Lampen in der ganzen Stadt beteiligt war? Eine einfache Aufgabe und eine meiner ersten...\n\nAber das ist jetzt egal. Nostalgie ist der Feind des Fortschritts. Das Lampenmaterial kann ich gut für meine aktuellen Arbeiten gebrauchen.\n\nDiese elenden Harpyien haben wahrscheinlich ihre Nester damit dekoriert. Bringt mir bitte alle mit, die Ihr finden könnt.", sourceObjective = "Besorgt 6 arkane Glimmlampen.", progress = "Das muss man sich mal vorstellen: ein Original von Lespin unter einem Laubhaufen. Was für eine Verschwendung.", completion = "Ausgezeichnet. Die werde ich einschmelzen und als Barren für meine nächsten Aufträge verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41308] = { id = 41308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzverstärkungen" }
quests[41309] = { id = 41309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangelrath", description = "Die dämonische Bestie vor Euch muss die gleiche sein, die den alten Brambley auf dem Gewissen hat...\n\nSchaut sie Euch an, wie sie da mit vollem Bauch herumliegt! Das ertrage ich einfach nicht, {name}! Wir müssen diese widerliche Kreatur abschlachten und Brambley rächen!\n\nWir sind schon so weit gekommen, {class}.\n\nWerdet Ihr mich auch diesmal unterstützen?!", sourceObjective = "Besiegt Mangelrath.", completion = "Es tut gut, ein freundliches Gesicht zu sehen. Ich weiß nicht, wie viel länger ich noch alleine durchgehalten hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[41311] = { id = 41311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Leystein", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Minenarbeiter. Wir haben diesen Leystein wirklich dringend gebraucht." }
