quests[41320] = { id = 41320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus ihren kalten, wilden Klauen", description = "Die Senkung des Schilds bietet eine einmalige Gelegenheit für neue Stile.\n\nFedern, Knochen und andere primitive Materialien sind plötzlich wieder in Mode. Wer hätte gedacht, dass sie von meinen Meisterwerken einmal genug haben würden?\n\nWagt Euch aus der Stadt heraus und sammelt Halsketten von den Harpyien auf den südlichen Klippen. Sie mit meinem Zeichen zu markieren, dürfte mir ein hübsches Sümmchen einbringen.", sourceObjective = "Sammelt 8 Harpyienhalsketten für Lespin ein.", progress = "Habt Ihr meine Halsketten? Sie nützen mir nichts an den Hälsen dieser... Kreaturen.", completion = "Diese elenden Kreaturen sind eine Geißel für unser schönes Land. Aber zumindest haben sie stilsicheren Schmuck getragen.\n\nOder vielleicht gefallen ihnen einfach nur glänzende Dinge.", sourceObjectiveStatus = "unverified-source-field" }
