quests[41330] = { id = 41330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoration Artifact Chosen" }
quests[41332] = { id = 41332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg im erlauchten Kreis", description = "Jetzt zählt Ihr zum Kreis der mächtigsten Druiden aller Zeiten, {name}!\n\nIch spüre, dass Malfurion eingetroffen ist. Wir sollten ihm von Euren Erfolgen berichten. Aber begleitet mich bitte zunächst ein Stück.", sourceObjective = "Begleitet Erzdruide Großhuf und sprecht dann mit Malfurion Sturmgrimm.", progress = "Ja?", completion = "Ich gratuliere Euch, Erzdruide {name}.\n\nWir werden in den kommenden Zeiten auf Eure Hilfe zählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41333] = { id = 41333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unverwüstlicher Wolfsbalg" }
quests[41334] = { id = 41334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moschusduftender Bärenbalg" }
quests[41335] = { id = 41335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Elemente", description = "Nobundo hat recht. Mit konventionellen Strategien lässt sich die Legion nicht besiegen. Das war die Lektion, die wir an der Verheerten Küste lernen mussten. Wir müssen die Welt nach geeigneten Waffen für den Kampf gegen die Legion absuchen!\n\nDer Schicksalshammer ist verschollen und muss geborgen werden. Rehgar und Erunak haben außerdem noch ein paar weitere Ideen. Aber was immer wir auch tun: Wir müssen uns beeilen.\n\nWir können die Optionen besprechen, aber die Entscheidung müsst Ihr treffen!", sourceObjective = "Sprecht mit Thrall und wählt das Artefakt aus, nach dem Ihr suchen wollt.", completion = "Eine gute Wahl. Aber wir haben keine Zeit zu verlieren. Lasst uns beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41336] = { id = 41336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grober Moschushirschbalg" }
