quests[41367] = { id = 41367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eilzustellung", description = "Ein Abenteurer hat es versäumt, wertvolle Beute einzusammeln. Wenn sie nicht nachträglich zugestellt wird, könnte dies ihm enorme emotionale Belastung bereiten.\n\nEuer Einsatzort ist die Eiskronenzitadelle, Euer Ziel sind die Überreste des Lichkönigs. Bergt das fehlende Objekt und überbringt es unverzüglich dem rechtmäßigen Besitzer – sein letzter bekannter Aufenthaltsort sind die Dampfteiche in Feralas.\n\nMein Assistent wird ein Portal bereitstellen, das Euch dorthin bringt. Einen Moment, bitte!", sourceObjective = "Bergt die vergessene Beute von den Überresten des Lichkönigs und sucht damit den rechtmäßigen Empfänger bei den Dampfteichen in Feralas auf.", progress = "Halt, Flegel. Womit wagt Ihr es, mich, den unvergleichlichen Johnny Imba, zu behelligen?", completion = "Ich hoffe, Ihr habt einen wirklich guten Grund, um meine Auszeit mit diesen üppigen Schönheiten zu unterbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41368] = { id = 41368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Post", description = "AN: MADAM GOYA, SCHATTENSEITE VON DALARAN\n\nDRINGEND!\n\nEILT!\n\nSOFORT AUSLIEFERN!", sourceObjective = "Liefert die verlorene Post an Madame Goya in der Schattenseite von Dalaran aus.", progress = "Was soll das? Ihr seid nicht der übliche Kurier...", completion = "Ah, eine Banknote. Die Zahlung von Steinbraue.\n\nUnd offensichtlich gerade noch rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[41394] = { id = 41394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Nebenverdienst", description = "Oh, wie einfältig Ihr seid, {race}.\n\nIch habe nicht etwa 'vergessen', nach meinem Triumph über diesen läppischen Lichkönig die Zügel aufzusammeln. Ich hielt es einfach nicht für nötig, da ich das mächtige Ross bereits letzte Woche bei einem Schlachtzug erhalten habe.\n\n<Johnny zeigt auf das Pferd zu seiner Linken.>\n\nAber da Ihr schon hier seid und verständlicherweise meinem unwiderstehlichen Charme verfallen seid, erlaube ich Euch, etwas für mich zu erledigen. Verkauft den überflüssigen Gaul in der Stadt beim stellvertretenden Resortdirektor. Zu einem kleinen Nebenverdienst sage ich nicht Nein.", sourceObjective = "Verkauft Unbesiegbars Zügel im Auftrag von Johnny Imba an God Wiedelspann.", progress = "Beeilt Euch, {class}. Je schneller Ihr fertig seid, desto früher könnt Ihr mich anhimmeln, wie all meine unzähligen Verehrer.", completion = "<Johnny hebt theatralisch seinen Arm und betrachtet sein Handgelenk, als würde er auf die Uhr schauen.>\n\nTsss, tsss, tsss, Ihr habt Euch ganz schön Zeit gelassen, was? Nun gut, das deckt vielleicht gerade so die Reparaturrechnungen aus meinen zahlreichen Schlachtzügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41395] = { id = 41395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gebührende Lohn", description = "Ihr habt mir treu gedient in den vergangenen paar Minuten, die wir Seite an Seite verbracht haben – Minuten, die ich nicht so schnell vergessen werde.\n\nFür Eure unverbrüchliche Treue habt Ihr Euch eine Belohnung verdient. Euch gebührt die unsterbliche Ehre, im Andenken an Glitzer sein Lieblingsspielzeug an seinem Grab niederzulegen.\n\nBitte, bitte – hebt Euch die Dankesreden für Glitzer auf. Es passiert nicht alle Tage, dass man ein Pferd aus STERNEN ehrt.", sourceObjective = "Legt Glitzers Lieblingsspielzeug an seinem Grab auf den Schlickfeldern im Vorgebirge des Hügellands nieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[41397] = { id = 41397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Riesenpaket", description = "Aufgrund zahlreicher Beschwerden in den letzten Monaten wurde ein Auslieferungsverbot für... r... r...\n\n<Der Postmeister kämpft mit den Tränen, sein Blick ist schmerzverzerrt.>\n\n... robusten Stein erteilt. Unsere Lager quellen förmlich über von robustem Stein – wenn wir ihn nicht ausliefern können, wissen wir bald nicht mehr wohin damit – \n\n<Das Gesicht des Postmeisters erhellt sich plötzlich.>\n\nIch hab's!\n\nHier in der Nähe gibt es ein altes Konsortiumportal, in dem wir die Steine abladen können, ohne dass jemand etwas davon mitbekommt!\n\nKönnt Ihr mir helfen, {name}? Die Steine sind extrem schwer.", sourceObjective = "Bringt 1.362 robuste Steine zum Portal der Astralen in Dalaran.", completion = "Ist es erledigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[41400] = { id = 41400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf: Pandarenküche!" }
quests[41405] = { id = 41405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf: Pandarenküche - Sungshin Eisentatz" }
quests[41406] = { id = 41406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf: Pandarenküche - Torg Unterhitz" }
quests[41408] = { id = 41408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf: Pandarenküche - Elling Trias" }
quests[41409] = { id = 41409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timing ist alles", description = "Spürt Ihr das, {name}? Das Nahen der Sashj'tar lässt das Wasser schäumen.\n\nIhr müsst jetzt zuschlagen...\n\nLasst mich zurück... Bombardiert die Naga mit den Fässern... irgendwie...\n\nBeschützt... Jandvik...", sourceObjective = "Reitet auf einem Azurwindpaddler und tötet 50 Naga der Sashj'tar mit den versiegelten Pulverfässern in der Azurwindbucht.", completion = "Fjolrik ist für Jandvik gestorben. Wir werden seinen Heldenmut in Erinnerung behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[41410] = { id = 41410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trockenes Pulver", description = "{name}... Euch hatte ich hier unten nicht erwartet.\n\nDie Sashj'tar sammeln sich... für einen Angriff auf Jandvik. Ich hatte einen Plan... sie mit diesen alten Pulverfässern auszulöschen.\n\nAber diese alten Knochen... waren den Naga nicht mehr gewachsen.\n\n<Fjolrik hustet ein wenig Blut.>\n\nWir haben nicht viel Zeit... für die Vorbereitungen.", sourceObjective = "Sammelt 5 versiegelte Pulverfässer aus den Schiffswracks in der Azurwindbucht.", progress = "Beeilt Euch, {name}.", completion = "<Fjolrik wirft Euch einen matten Blick zu.>\n\nIhr habt es rechtzeitig geschafft...", sourceObjectiveStatus = "unverified-source-field" }
quests[41411] = { id = 41411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Post", description = "AN: MADAM GOYA, SCHATTENSEITE VON DALARAN\n\nDRINGEND!\n\nEILT!\n\nSOFORT AUSLIEFERN!", sourceObjective = "Liefert die verlorene Post an Madame Goya in der Schattenseite von Dalaran aus.", progress = "Was soll das? Ihr seid nicht der übliche Kurier...", completion = "Ah, eine Banknote. Die Zahlung von Steinbraue.\n\nUnd offensichtlich gerade noch rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[41412] = { id = 41412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Retreat" }
quests[41413] = { id = 41413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was soll schon schiefgehen?", sourceObjective = "Der Erzdruide als Lehrmeister? Da freut Zen'kiki sich aber!\n\nIch werd im Gegenzug für Eure Hilfe dafür sorg'n, dass Ihr Euch hier wohlfühlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41414] = { id = 41414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesschwinges Waffen" }
quests[41415] = { id = 41415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Jägers", description = "Ich weiß, dass wir uns noch nie begegnet sind, aber Ihr werdet noch früh genug von meinem Orden erfahren. Wir haben jetzt keine Zeit für Höflichkeiten.\n\nDie Legion ist zurück in Azeroth, und sie ist stärker als je zuvor. Wir brauchen neue Waffen für den Kampf gegen sie.\n\nIch habe hier in Dalaran drei Personen kennengelernt, die über Hinweise auf möglicherweise kriegsentscheidende, antike Artefakte verfügen. Diese Waffen kann nur ein <wahrer Meisterjäger/eine wahre Meisterjägerin> beschaffen.\n\nSprecht mit den drei Personen und entscheidet, nach welcher Waffe Ihr zuerst suchen wollt.", sourceObjective = "Untersucht die Hinweise auf die drei Artefaktwaffen.", progress = "Habt Ihr schon entschieden, welchem Hinweis Ihr nachgehen wollt?", completion = "Alle drei Waffen, von denen Ihr erfahren habt, würden einen großen Vorteil im Kampf gegen die Legion darstellen.\n\nAber Ihr könnt den Feldzug nur mit einer von ihnen beginnen. Ihr müsst Euch also entscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41416] = { id = 41416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückeroberung des Himmelshorns" }
quests[41420] = { id = 41420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm der Wächterinnen: Der Hort des Nachtwächters" }
quests[41421] = { id = 41421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm der Wächterinnen: Der Hort des Nachtwächters" }
quests[41422] = { id = 41422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notwendige Vorbereitungen", description = "G'Hanir ist... ist...\n\n<Mylune wischt sich die Tränen aus den Augen und schnieft.>\n\nVerderbt! Der Alptraum hat sich aus den Tiefen des Traums erhoben. Es ging alles so schnell...\n\nIch habe es geschafft, den Stab innerhalb des Traums hierher zu bringen, bevor er der Verderbnis vollständig anheimfallen konnte. Vorerst ruht er... doch ich befürchte, uns bleibt nicht viel Zeit.\n\nIhr müsst Euch darauf vorbereiten, G'Hanir aus dem Traum zu holen. Schöpft Wasser aus dem heiligen Mondbrunnen am nördlichen Rand des Hains und erhaltet den Segen eines Urtums.\n\nSchnell, jeder Augenblick ist kostbar!", sourceObjective = "Füllt einen Becher mit Mondbrunnenwasser und erhaltet den Segen von Blattbart dem Erzähler.", progress = "Seid Ihr bereit?", completion = "<Mylunes Miene hellt sich auf.>\n\nDann besteht noch Hoffnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[41423] = { id = 41423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungsquest im Adelsviertel von Suramar" }
quests[41424] = { id = 41424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroische Belohnungsquest im Adelsviertel von Suramar" }
quests[41425] = { id = 41425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkene Feinde", description = "Die Gezeitenherrin... füllt die Ränge ihrer Streitkräfte mit gewaltigen Naga... und Meeresriesen.\n\nJandvik kann... ihrer gemeinsamen Kraft nicht standhalten.\n\nTötet sie... bevor sie an die Küste gelangen...", sourceObjective = "Tötet 6 Aufseher der Sashj'tar und 6 Grubengängerplünderer in der Azurwindbucht.", completion = "Die Streitkräfte der Sashj'tar sind viel zahlreicher, als ich mir vorgestellt hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[41426] = { id = 41426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihrem Willen zum Trotze", description = "Als mich die Naga hier herunterbrachten, sah ich viele meiner Vrykul den Meeresboden bearbeiten. An ihren Gesichtern hingen... Tintenfische.\n\nWas immer sie auch sein mögen, diese Tiere scheinen meine Leute zu kontrollieren und sie zu zwingen, für die Naga zu schuften.\n\nIch weiß nicht, was passiert, wenn Ihr diese Tintenfische entfernt. Doch mir wäre lieber, mein Volk stirbt, als dass es von den Naga versklavt wird.\n\nSprecht in Jandvik mit mir, wenn es erledigt ist.", sourceObjective = "Entfernt wabernde Willenbrecher von 6 besessenen Vrykul in der Azurwindbucht.", completion = "Ich muss Euch für die Vrykul danken, die Ihr heute gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41427] = { id = 41427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abge-Vrekt" }
