quests[41435] = { id = 41435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glatte Leysteinvorkommen" }
quests[41436] = { id = 41436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In tiefem Schlummer", description = "Auf diesem Bett werdet Ihr in tiefen Schlummer verfallen, der Euch in den Traum führt.\n\nTrinkt das mitgebrachte Mondwasser, sobald Ihr es Euch gemütlich gemacht habt. Danach werde ich Euch leiten.\n\nJetzt aber schnell. Mit jeder Minute entschwindet G'Hanir weiter in die Dunkelheit.", sourceObjective = "Begebt Euch in den Smaragdgrünen Traum, um G'Hanir zurückzuholen.", progress = "Konntet Ihr G'Hanir an Euch bringen?", completion = "Durch die Ausbreitung der Dunkelheit ist es keine einfache Aufgabe, in den Traum zu dringen. Nur wenige Druiden wagen es, doch ich fürchte, Ihr seid noch lange nicht am Ende Eurer Reise angelangt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41437] = { id = 41437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feine Leysteinvorkommen" }
