quests[41448] = { id = 41448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Teufelsschiefervorkommen" }
quests[41449] = { id = 41449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsamer Traum", description = "Leider kann ich Euch nicht wirklich dabei helfen, den Smaragdgrünen Traum zu betreten. Wir Dryaden lassen unsere Körper einfach von einer Daseinsebene in die andere gleiten.\n\nDoch das ist kein Problem: Naralex hat seine Hilfe angeboten!\n\nBegebt Euch bis in die tiefsten Tiefen der Traumhöhle von Tel'andu. Naralex bereitet dort schon alles für Euch vor.", sourceObjective = "Sucht nach Naralex tief in der Traumhöhle von Tel'andu.", completion = "Meine Vorbereitungen sind abgeschlossen. Seid Ihr bereit, den Traum zu betreten?", sourceObjectiveStatus = "unverified-source-field" }
quests[41451] = { id = 41451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Hrydshal" }
quests[41452] = { id = 41452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaoskatzen", description = "Seid gegrüßt, <Fremder/Fremde>!\n\n<Mayruna verbeugt sich vor Euch.>\n\nWir kamen vor Kurzem aus Val'sharah angereist und hofften, uns hier niederlassen zu können. Unsere Reise war anstrengend und wir sind erschöpft.\n\nDiese Eulenkatzen haben Chaos im Lager angerichtet, wie Ihr ja selbst seht. Wärt Ihr so freundlich, uns bei den Aufräumarbeiten zur Hand zu gehen?\n\nUnd danach könnt Ihr uns ja dabei helfen, einen neuen Mondbrunnen zu errichten!", sourceObjective = "Räumt das Lager auf.", progress = "Ist alles wieder an seinem richtigen Platz?", completion = "Alles ist am rechten Platz. Wir werden uns schon bald richtig heimisch fühlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41453] = { id = 41453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab nach Hause", description = "Bei der Errichtung eines Mondbrunnens muss man als Erstes den Segen der heimischen Tierwelt erhalten. \n\nUnsere friedliche Koexistenz hängt von ihrem guten Willen ab, und ein Mondbrunnen gedeiht durch diese Energien. In Verbindung mit Elunes Licht kann ein Mondbrunnen seine Umgebung über Jahre hinweg läutern.\n\nZunächst müssen wir also Kreaturen finden, die uns ihren Segen geben. Wir können mit diesen Eulenkätzchen beginnen.\n\nSie rannten bei Euren Aufräumarbeiten davon, aber ich sah eines direkt vor der Brücke sitzen. \n\nVersucht herauszufinden, wo es lebt!", sourceObjective = "Scheucht das verirrte Eulenkätzchen über die Brücke und bringt es zu seiner Familie zurück.", progress = "Habt Ihr die Kleine zurückgebracht?", completion = "Also das nenne ich eine interessante Wendung.", sourceObjectiveStatus = "unverified-source-field" }
quests[41454] = { id = 41454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzende Leysteinablagerung" }
quests[41455] = { id = 41455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmernde Leysteinablagerung" }
quests[41457] = { id = 41457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strahlende Leysteinablagerung" }
quests[41458] = { id = 41458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehärtete Leysteinablagerung" }
quests[41459] = { id = 41459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dichte Leysteinablagerung" }
quests[41460] = { id = 41460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursprüngliche Leysteinablagerung" }
quests[41461] = { id = 41461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösartige Teufelsschieferablagerung" }
quests[41462] = { id = 41462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ärger kommt auf großen Füßen", description = "Die Haut des Ettins weist viele flache Kratzer und Bisswunden auf. Anscheinend hat er die einheimischen Eulenkatzen schon seit einer ganzen Weile schikaniert.\n\nMardranel Waldherz hätte bestimmt Interesse daran.", sourceObjective = "Bringt das groteske Ettinleder zu Mardranel Waldherz.", completion = "Ahhhh... Gut gemacht. Ich bin sicher, unsere pelzigen Freunde hier sind für Eure Bemühungen sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[41463] = { id = 41463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwegs vermisst", description = "Während wir uns aus Val'sharah zurückgezogen haben, wurde unsere Gruppe kurzzeitig durch eine Auseinandersetzung mit einigen Satyrn an der Grenze getrennt.\n\nEiner von uns hat es nicht bis hierher geschafft: Mythandros' Bruder, Kalendros. Ich möchte Euch bitten, zu versuchen ihn zu finden.\n\nDurchsucht die Wälder kurz vor der Brücke, die zurück nach Val'sharah führt.", sourceObjective = "Sucht nach Kalendros Eisenhain.", completion = "Wie gut, dass Mayruna Hilfe geschickt hat. Ich hatte die Hoffnung schon fast aufgegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[41464] = { id = 41464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht hier, nicht jetzt, niemals", description = "Ich kann und werde das, was hier geschieht, nicht akzeptieren. Mein Körper widersetzt sich mir, aber ich werde dem ein Ende setzen.\n\n<Er blickt Euch an.> Ihr werdet dem ein Ende setzen.\n\nEine Wurzel des verderbten Weltenbaums Shaladrassil hat sich irgendwie einen Weg aus dem Boden heraus zu diesem unberührten Ort gebahnt, und die Satyrn der Schattenteufel arbeiten bereits hart daran, Suramar zu verderben.\n\nHaltet sie auf. Tötet die Satyrn, nehmt ihre Hörner und durchbohrt mit ihnen die Totems.\n\nNur dann gibt es Hoffnung, das hier ins Reine zu bringen.", sourceObjective = "Verwendet Satyrhörner, um 3 Totems der Schattenteufel zu zerstören.", progress = "Habt Ihr sie aufhalten können, {race}?", completion = "Ich bin erleichtert, obwohl wir noch mehr tun müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41465] = { id = 41465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antikschmuck: Schnalle eines Schnösels", description = "Unerfahrene Händler haben Angst, wegen schlechter Produkte ihr Ansehen zu verlieren. Meister hingegen haben diese Sorge wegen schlechter Kunden.\n\nNaltethis Federklinge nimmt sich für seine Stellung zu viel heraus. Folglich hat er bei der Stadtelite einiges an Ruf verloren.\n\nIch habe diesem Mann eine Brosche verkauft, die er als Schnalle an seinem Umhang trägt. Ich achte stets darauf, nur an diejenigen zu verkaufen, die von höherem Stand sind als ich selbst.\n\nMeine Stücke behalten ihren Glanz auf ewig, doch mein Name und mein guter Ruf sind nicht so beständig. Nehmt ihm mein Eigentum ab, bevor er mir noch mehr Schande bereitet.", sourceObjective = "Besorgt Lespins Brosche von Naltethis Federklinge.", progress = "Dieser Dummkopf wird Jahre harter Arbeit zunichtemachen. Der Fall verläuft immer schneller als der Aufstieg...", completion = "Aha, seht nur her! Ich habe Euch doch gesagt, meine Sachen behalten immer ihren Glanz. Jetzt bringt mich nichts mehr mit diesem Narren in Verbindung.\n\nWie? Ein Plan, um seine Stellung ins Wanken zu bringen? Wie auch immer, der Schaden ist schon angerichtet. Vorsicht ist immer besser als Nachsicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[41466] = { id = 41466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antikschmuck: Moderne Kunst", description = "Ein Anfänger blickt auf seine bisherige Händlerkarriere als lehrreiche Erfahrung zurück. Ein Meister weiß, dass manches besser in Vergessenheit geraten sollte.\n\nIch war... einst eitel, vor Jahrhunderten. Ich wollte mich unbedingt beweisen und habe einen gewagten Auftrag angenommen.\n\nFindet... es und bringt es zurück. Ihr werdet wissen, was \"es\" ist, wenn Ihr es seht.\n\nSein Besitzer wohnt in Nähe der Villa südlich dieses Hofes.", sourceObjective = "Sucht nach Mornath und holt Lespins \"Kunst\" zurück.", progress = "Er war so begeistert, so ehrgeizig. Ich habe seine Vision geteilt und das Stück genau nach seinen Angaben maßgefertigt. Wunderbare filigrane Arbeit und Emaille in Form einer schrecklichen Waffe...", completion = "Bei der Magistrix. Ich hatte vergessen, wie hässlich dieses Ding ist. Natürlich makellos gearbeitet. Aber... urks. Ich sollte es einschmelzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41467] = { id = 41467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine andere Wahl", description = "Nehmt diese Fackel, {name}.\n\nWir können die Alptraumverderbnis nicht beseitigen, wenn sie sich einmal festgesetzt hat. Wir können nur hoffen, ihre Manifestationen zu zerstören.\n\nVerbrennt die Wurzel. Erst dann können wir in Suramar ruhig schlafen.", sourceObjective = "Verbrennt die Wurzel von Shaladrassil.", completion = "Welch verstörende Geschichte!", sourceObjectiveStatus = "unverified-source-field" }
quests[41468] = { id = 41468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrin der Klaue", description = "Vor zehntausend Jahren gab der große Waldwächter Ursoc sein Leben für diese Welt. Nach dem Tod des Wächters wurden seine Klauen vor jenen versteckt, die ihre Macht für das Böse nutzen wollten.\n\nLea Steinpfote und ihre Druiden der Klaue sehen Ursoc als Vorbild und folgen seinem Beispiel. Wenn irgendjemand weiß, wo die Klauen sind, dann ist es Lea.\n\nSie und ihre Druiden der Klaue leben in der Traumhöhle von Tel'andu nördlich von hier.", sourceObjective = "Sucht Lea Steinpfote auf.", completion = "Ursocs Klauen?\n\nIch hätte nicht gedacht, dass ich zu meinen Lebzeiten noch einmal davon hören würde. Ist die Lage wirklich so düster? Sie wurden aus gutem Grund verborgen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41469] = { id = 41469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Eisenhainzuflucht", description = "Wir haben drei Segen von Kreaturen erhalten, mit denen wir uns dieses Land teilen.\n\nKombiniert mit einem Segen von Elune wird der Mondbrunnen noch viele Jahre über dieses Land wachen.\n\nTrefft Euch mit Mythandros in der Zuflucht. Er möchte Euch sicher am Ritual teilhaben lassen.", sourceObjective = "Sucht nach Mythandros in der Eisenhainzuflucht.", completion = "Willkommen zurück. Dann sind wir bereit zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41473] = { id = 41473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rothuf der Urahn", description = "Während Ihr damit beschäftigt wart, den Eulenkatzen auf der anderen Flussseite zu helfen, sind Mythandros und Solendra weiter nach Osten vorgedrungen.\n\nIch glaube, Mythandros hat vielleicht die nächste Kreatur gefunden, die uns ihren Segen gewähren könnte.\n\nEs gibt eine abgelegene Lichtung entlang der Flussbiegung im Nordosten. Dort findet Ihr möglicherweise unseren neuen Verbündeten, einen alten Hirsch namens Rothuf.", sourceObjective = "Spürt Mythandros und Rothuf den Urahn auf.", completion = "Dieser nette Herr erzählte mir gerade, wie sehr er seinen Wald liebt. Helfen wir ihm doch!", sourceObjectiveStatus = "unverified-source-field" }
quests[41474] = { id = 41474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dünger für die Zukunft", description = "Wie die meisten Pflanzenfresser vertilgen unsere Geweihe tragenden Freunde alles, was grün genug ist, es zu kauen.\n\nAllerdings habe ich bemerkt, dass sie diese dunklen Grasflecken aufsuchen, wenn sie die Wahl haben. Ich glaube, wir können uns ihr Wohlwollen verdienen, indem wir dem Wald dabei helfen, noch mehr von diesem nahrhaften Hirschfutter hervorzubringen.\n\nIch werde Euch so viele Samen zur Verfügung stellen, wie Ihr benötigt. Ihr müsst nur passende Muttererde für die Saat suchen und sie aussäen. Unsere Magie wird den Rest erledigen.", sourceObjective = "Pflanzt 5 saftige Grassamen in fruchtbaren Boden.", completion = "Sie sehen bereits wohlgenährter aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[41475] = { id = 41475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit scharfen Zähnen", description = "Also, {name}, versteht mich nicht falsch. Ich bin ein Druide. Ich weiß, dass es in der Natur Gleichgewicht geben muss.\n\nRaubtiere müssen fressen und andere Tiere werden gejagt. Ich weiß auch, dass es Konsequenzen hat, wenn man an diesem Gleichgewicht herumspielt.\n\nDeshalb habe ich es auf mich genommen, dieses Land zu durchstreifen und gewisse... nun... Berechnungen anzustellen.\n\nTötet nur eine geringe Anzahl der Wölfe, denen Ihr begegnet, davon einen Alpha. Dadurch sollte ihre Zahl ausreichend verringert werden, damit die Zobelhörner gedeihen können, ohne den Fluss der Dinge hier zu stören.", sourceObjective = "Tötet 8 Knurrer von Suramar und Düsterfang.", completion = "Letztendlich werden sie alle gedeihen. Denn mit mehr Zobelhörnern werden sich auch die Wölfe in Zukunft besser nähren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[41478] = { id = 41478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Segen", description = "Meine Freundin Solendra Federdaun hat sich aufgemacht, um den Lebensraum der hiesigen Nachtsäbler zu erforschen.\n\nDa wir bereits den Segen der Federmähnen und der Zobelhörner erhalten haben, benötigen wir nur noch den Segen der Nachtsäbler. Ihr findet Solendra im Norden, auf der anderen Seite dieser Lichtung.", sourceObjective = "Sprecht mit Solendra Federdaun.", completion = "Willkommen, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41479] = { id = 41479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliche Feinde", description = "Seit wir hier angekommen sind, habe ich dieses Land erkundet. In diese Gegend sind Basilisken aus den Schluchten im Osten eingewandert und machen den Nachtsäblern ihr Territorium streitig.\n\nUm ihren Segen zu erhalten, sollten wir ihnen ermöglichen, hierher zurückzukehren.\n\nDazu müsst Ihr die Basilisken töten, die jetzt einen größeren Teil dieser Gegend beanspruchen, als ihnen zusteht, {race}.", sourceObjective = "Tötet 8 Manaschuppenbasilisken.", completion = "Gut gemacht, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41480] = { id = 41480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaseher", description = "Es gibt hier einen Basilisken, der so viel Nachtsäblerfleisch gefressen hat, dass er kaum noch aus seiner Höhle herauskommt.\n\nDas können wir zu unserem Vorteil nutzen.\n\nTötet den Basilisken Manaseher, um ein Exempel für all die anderen zu statuieren, die sich zu weit von ihrer angestammten Heimat entfernt haben.", sourceObjective = "Tötet den Basiliskenfürsten Manaseher.", completion = "Was für eine gefräßige Kreatur.", sourceObjectiveStatus = "unverified-source-field" }
quests[41481] = { id = 41481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelzerstörer" }
