quests[41484] = { id = 41484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelzerstörer" }
quests[41485] = { id = 41485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondwisperrettung", description = "Als Druidin verstehe ich, dass Raubtiere Beute schlagen müssen. Fleischfressende Kreaturen benötigen Fleisch.\n\nAber das...\n\n<Solendra zeigt zornig auf einen versteinerten Nachtsäbler in der Nähe.>\n\nDas ist nur noch traurig. Befreit sie, {race}. Nehmt meinen Segen und befreit sie von diesem sinnlosen Leiden.", sourceObjective = "Befreit 5 versteinerte Nachtsäbler mithilfe von Solendras Geschenk.", completion = "Über diese Nachricht bin ich sehr erleichtert, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41486] = { id = 41486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelzerstörer" }
