quests[41493] = { id = 41493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelzerstörer" }
quests[41494] = { id = 41494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segensreiche Übernahme", description = "Ihr habt Eure Sache sehr gut gemacht, {race}.\n\nJetzt bleibt nur noch, die Segnungen in einem Ritualbündel zusammenzubringen und den Mondbrunnen mit dessen Energie zu durchwirken. Wenn das getan ist, wird Mayruna ein wenig Wasser von einem geläuterten Mondbrunnen hinzufügen. Dann wird dieses Land so lange geschützt sein, wie wir darin leben.\n\nDies ist ein großer Moment, <mein Freund/meine Liebe>. Ihr werdet gleich <Zeuge/Zeugin> eines Rituals, das nicht oft in der Gegenwart Fremder abgehalten wird.\n\nIch überlasse Euch die Ehre: Legt einfach das Ritualbündel in das geheiligte, stille Wasser. Wir übernehmen dann den Rest.", sourceObjective = "Segnet das stille Wasser mithilfe des Ritualbündels und werdet dann <Zeuge/Zeugin> der Erschaffung des Brunnens.", progress = "Dies ist ein historischer Moment, {race}.", completion = "All dies habt Ihr durch Eure Hilfe ermöglicht. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[41495] = { id = 41495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brillante Leysteinflöze" }
quests[41496] = { id = 41496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohe Leysteinflöze" }
quests[41497] = { id = 41497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Leysteinflöze" }
quests[41498] = { id = 41498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leysteinbasilisken" }
quests[41499] = { id = 41499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tintenfisch auf dem Trockenen", description = "Toryl hat mir von diesen tintenfischähnlichen Kreaturen erzählt, die meine Brüder kontrollieren.\n\nSo etwas habe ich in der Gegend um Jandvik noch nie zuvor gesehen. Die Naga müssen sie von wo auch immer mitgebracht haben.\n\nIch will nicht, dass noch mehr meiner Leute das Schicksal ereilt, von den Naga kontrolliert zu werden.\n\nFindet heraus, wo diese Kreaturen herkommen, und setzt dem ein Ende.", sourceObjective = "Zerstört 5 Willenbrecherinkubatoren in den Ruinen der Sashj'tar.", completion = "Die Naga werden niemanden von meinem Volk mehr unterwerfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41500] = { id = 41500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leywürmer" }
