quests[41510] = { id = 41510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeroth braucht Euch", description = "Wir Schamanen unter Eurem Befehl werden Euch in Eurem Kampf gegen die Legion unterstützen. Ihr könnt unsere Aktionen von hier aus lenken.\n\nSucht Berater Sevel ein Stückchen südlich von hier auf und geht an die Späherkarte, über die Ihr Eure Anhänger führen könnt. Auf dieser Späherkarte werden wir zudem verschiedene beachtenswerte Punkte auf den Verheerten Inseln markieren.\n\nAzeroth braucht Euch, <Scharfseher/Scharfseherin>! Geht jetzt zur Späherkarte und wählt unseren ersten Angriffspunkt aus.", sourceObjective = "Wählt Euren ersten Angriffspunkt auf den Verheerten Inseln aus.", completion = "Eine gute Entscheidung, Scharfseher. Hinter mir habe ich ein Astralportal nach Dalaran geöffnet, damit unsere Leute schnell zwischen unseren Operationsbasen und den Verheerten Inseln hin- und herreisen können. Geht hindurch, um nach Dalaran zurückzukehren. Ihr könnt das Portal jederzeit verwenden, um hierher zurückzukommen und Euer Artefakt zu verstärken oder Eure Anhänger zu befehligen.\n\nMögen die Elemente Euch sicher leiten, Scharfseher.", sourceObjectiveStatus = "unverified-source-field" }
